// Normaliza payload del landing y arma asunto / contenido por tipo
const body = $input.first().json.body || $input.first().json;

const safe = (s) => String(s ?? '').trim();
const escape = (s) => safe(s).replace(/[&<>"']/g, (c) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));

const name = safe(body.name);
const email = safe(body.email).toLowerCase();
const type = safe(body.type);
const type_label = safe(body.type_label) || type;
const message = safe(body.message);

// Asunto del mail al equipo
const teamSubject = `[Finy Web] [${type_label}] ${name}`;

// Mensajes de auto-reply por tipo
const REPLIES = {
  soporte: {
    pill: 'Soporte técnico',
    title: '¡Hola, ' + escape(name) + '! 👋',
    body: 'Recibimos tu mensaje y ya estamos revisando lo que contás. Nuestro equipo se pone en contacto en menos de 24 horas para ayudarte a resolverlo.',
  },
  propuesta: {
    pill: 'Propuesta de negocio',
    title: '¡Gracias por escribirnos, ' + escape(name) + '!',
    body: 'Recibimos tu propuesta y la vamos a revisar con detalle. Si encaja con lo que estamos buscando, te respondemos en menos de 48 horas para coordinar una llamada.',
  },
  baja: {
    pill: 'Cancelación / baja',
    title: 'Recibimos tu pedido, ' + escape(name),
    body: 'Lamentamos que te vayas. Procesamos tu solicitud de baja y te confirmamos por mail en menos de 24 horas. Si querés contarnos qué te llevó a cancelar, sería de mucha ayuda — leemos cada respuesta.',
  },
  otro: {
    pill: 'Tu mensaje',
    title: '¡Hola, ' + escape(name) + '!',
    body: 'Recibimos tu mensaje. Te respondemos en menos de 24 horas con lo que necesites.',
  },
};
const rep = REPLIES[type] || REPLIES.otro;

const userSubject = '[Finy] Recibimos tu mensaje';

// HTML auto-reply (estilo del template existente)
const userHtml = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Finy</title>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700&display=swap" rel="stylesheet">
<style>
body{margin:0;padding:0;background:#F5F5F5;font-family:'Inter',Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased;color:#202020}
table{border-collapse:collapse;width:100%}
img{display:block;max-width:100%;height:auto;border:0}
a{text-decoration:none!important;color:inherit!important}
.main-wrapper{background:#F5F5F5;padding:40px 10px}
.logo{max-width:600px;margin:0 auto 30px;text-align:center}
.card{max-width:600px;margin:0 auto;background:#FFFFFF;border-radius:16px;border:1px solid #E5E5E5;overflow:hidden;margin-bottom:20px}
.pad{padding:40px}
h1{font-size:24px;font-weight:700;margin:0 0 16px;letter-spacing:-.5px;line-height:1.3}
p{font-size:15px;line-height:1.6;color:#505050;margin:0 0 20px}
.pill{background:#F5F5F5;color:#666;font-size:11px;font-weight:700;padding:4px 10px;border-radius:6px;text-transform:uppercase;letter-spacing:.5px;display:inline-block;margin-bottom:15px}
.box{background:#FAFAFA;border-left:4px solid #cefd55;padding:18px 20px;border-radius:0 8px 8px 0;margin-bottom:24px;border-top:1px solid #E5E5E5;border-right:1px solid #E5E5E5;border-bottom:1px solid #E5E5E5;font-size:14px;color:#505050;line-height:1.55;white-space:pre-wrap}
.divider{height:1px;background:#F0F0F0;width:100%;margin:25px 0}
.footer{text-align:center;margin-top:30px;font-size:12px;color:#999}
@media (max-width:600px){.pad{padding:24px}h1{font-size:22px}}
</style>
</head>
<body>
<div class="main-wrapper">
  <div class="logo">
    <a href="https://www.finyapp.io/" target="_blank">
      <img src="https://zqniepbsjrvuypxyagaz.supabase.co/storage/v1/object/public/newsletter-assets/finy_email_logo.png" alt="Finy" width="80">
    </a>
  </div>
  <div class="card">
    <div class="pad">
      <span class="pill">${rep.pill}</span>
      <h1>${rep.title}</h1>
      <p>${rep.body}</p>
      <div class="divider"></div>
      <p style="font-size:13px;color:#999;margin-bottom:8px">Tu mensaje:</p>
      <div class="box">${escape(message)}</div>
      <p style="margin-bottom:0;font-weight:600;color:#202020">— El equipo de Finy</p>
    </div>
  </div>
  <div class="footer"><p>Finy App © 2026<br>Respondés a este mail si necesitás algo más.</p></div>
</div>
</body>
</html>`;

// HTML notificación al equipo
const teamHtml = `<!DOCTYPE html>
<html><body style="font-family:system-ui,-apple-system,sans-serif;max-width:560px;margin:0 auto;padding:24px;color:#18181b">
  <h2 style="margin:0 0 8px;font-size:18px">Nueva consulta — finyapp.io</h2>
  <p style="margin:0 0 16px;color:#71717a;font-size:13px">${escape(type_label)}</p>
  <table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:18px">
    <tr><td style="padding:6px 0;color:#71717a;width:80px">Nombre</td><td style="padding:6px 0;font-weight:600">${escape(name)}</td></tr>
    <tr><td style="padding:6px 0;color:#71717a">Email</td><td style="padding:6px 0;font-weight:600"><a href="mailto:${escape(email)}" style="color:#18181b;text-decoration:underline">${escape(email)}</a></td></tr>
  </table>
  <div style="background:#f4f4f5;border-radius:12px;padding:16px;font-size:14px;line-height:1.6;white-space:pre-wrap">${escape(message)}</div>
  <p style="font-size:12px;color:#a1a1aa;margin-top:18px">Respondé directo: este mail tiene Reply-To configurado al usuario.</p>
</body></html>`;

return [{
  json: {
    name,
    email,
    type,
    type_label,
    message,
    teamSubject,
    teamHtml,
    userSubject,
    userHtml,
  },
}];
